import{_ as t,o as r,c as i,a2 as n}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"Education Reminder Scheduled Delivery Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-06-19-education-reminder-vapid-sync-design.md","filePath":"superpowers/specs/2026-06-19-education-reminder-vapid-sync-design.md"}'),a={name:"superpowers/specs/2026-06-19-education-reminder-vapid-sync-design.md"};function o(s,e,d,c,l,u){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="education-reminder-scheduled-delivery-design" tabindex="-1">Education Reminder Scheduled Delivery Design <a class="header-anchor" href="#education-reminder-scheduled-delivery-design" aria-label="Permalink to &quot;Education Reminder Scheduled Delivery Design&quot;">​</a></h1><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>The manager education-reminder button succeeds from the Next.js server, while the scheduled Supabase Edge Function receives HTTP 403 from the push service.</p><p>Production diagnostics exposed the exact push-service response: the VAPID credentials used by the Edge Function do not correspond to the credentials used to create the browser subscriptions.</p><h2 id="root-cause" tabindex="-1">Root Cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root Cause&quot;">​</a></h2><p>The browser subscriptions were created with the VAPID public key embedded in the Vercel production client. The matching private key is a sensitive Vercel environment variable and cannot be exported through the CLI. The Edge Function held a separate key pair, so its direct Web Push requests were rejected.</p><p>Maintaining two independent Web Push senders also allowed their runtime, credentials, and behavior to drift.</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h2><ol><li>Keep scheduling, duplicate prevention, and run-history recording in the Supabase Edge Function.</li><li>Move actual scheduled delivery through the existing Next.js server sender used by the working manager button.</li><li>Add shared-secret authentication to the Next.js cron route while preserving Vercel Cron user-agent support.</li><li>Configure the Edge Function with the stable production cron API URL and call it with <code>x-cron-secret</code>.</li><li>Remove VAPID and Web Push implementation details from the Edge Function.</li></ol><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><ul><li>The Edge Function rejects requests without its cron secret.</li><li>The Next.js cron route rejects requests that are neither Vercel Cron nor authenticated with the shared secret.</li><li>Non-success downstream responses become failed push-run records with the HTTP status and returned error.</li><li>Successful downstream results are stored unchanged in <code>push_notification_runs</code>.</li></ul><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><ul><li>Route test for Vercel Cron authentication.</li><li>Route test for shared-secret authentication.</li><li>Route test for unauthorized requests.</li><li>Client tests for request headers, result parsing, and downstream failure details.</li><li>TypeScript, full Vitest, lint, and production build checks.</li><li>Production invocation through the Supabase Edge Function with temporary schedule restoration and database verification.</li></ul><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><p>The same <code>EDUCATION_REMINDER_CRON_SECRET</code> is configured in Vercel production and Supabase. Supabase also receives <code>EDUCATION_REMINDER_API_URL=https://ollbareun.vercel.app/api/cron/education-reminders</code>. The Vercel deployment must complete before the final Edge Function production test.</p>',15)])])}const m=t(a,[["render",o]]);export{p as __pageData,m as default};
